import {escapeHTML as e} from './finance.js';
export function createAuthUI(ctx){
 let mode='signup',email='',name='',error='',sending=false,loading=false,lastMode='';
 const {api,icon}=ctx;
 function refresh(){ctx.render();}
 function render(){const signup=mode==='signup',ready=api.configured();return `<main class="auth-scene" id="main"><div class="auth-orb one" aria-hidden="true"></div><div class="auth-orb two" aria-hidden="true"></div><div class="auth-grid" aria-hidden="true"></div><header class="auth-top"><a class="brand auth-brand" href="${location.pathname}" aria-label="Alva, início"><img src="./logo.svg" alt="">alva<span>.</span></a><span class="auth-top-caption">SEU PRÓXIMO PASSO</span><button class="button glass-button" data-auth-action="demo">Conhecer a Alva${icon('arrow')}</button></header><div class="auth-layout"><section class="auth-story"><div class="auth-eyebrow"><span></span>CLAREZA PARA HOJE. PLANOS PARA AMANHÃ.</div><h1>Seu dinheiro.<br> Um novo <em>começo.</em></h1><p>Organize a vida, tire os sonhos do papel<br> e cuide do seu negócio. Tudo no seu ritmo.</p><div class="auth-preview" aria-label="Exemplo ilustrativo de planejamento"><div class="preview-head"><span class="preview-symbol">${icon('leaf')}</span><span>Pequenos passos.<br><strong>Grandes possibilidades.</strong></span><span class="preview-dots" aria-hidden="true">•••</span></div><div class="preview-goal"><div><span>Minha reserva</span><strong>Um plano para o futuro${icon('target')}</strong></div><span class="preview-progress" aria-hidden="true"><i></i></span><small>Um pouco hoje. Mais tranquilidade amanhã.</small></div><div class="preview-bottom"><span>${icon('check')}Vida pessoal organizada</span><span>${icon('business')}Negócio no controle</span></div><div class="preview-float" aria-hidden="true">${icon('spark')}Cada passo conta<span>Você está construindo seu amanhã.</span></div></div><div class="auth-story-foot">${icon('lock')}Um espaço só seu, da vida pessoal ao negócio.</div></section><section class="auth-card" data-auth-mode="${mode}" aria-labelledby="auth-title" ${sending?'aria-busy="true"':''}><div class="auth-card-top"><div class="auth-card-icon">${icon(loading?'refresh':'lock')}</div><span class="auth-card-badge"><i></i>SEU ESPAÇO PESSOAL</span></div>${loading?`<div class="auth-loading"><h2 id="auth-title">Abrindo seu espaço…</h2><p>Estamos buscando os dados da sua conta.</p><span class="auth-loading-line" aria-hidden="true"></span></div>`:`<div class="auth-mode-tabs" role="group" aria-label="Tipo de acesso"><button class="${signup?'active':''}" data-auth-mode="signup" aria-pressed="${signup}" type="button" ${sending?'disabled':''}>Criar conta</button><button class="${!signup?'active':''}" data-auth-mode="login" aria-pressed="${!signup}" type="button" ${sending?'disabled':''}>Entrar</button></div><div class="auth-form-content"><h2 id="auth-title">${signup?'Seu próximo passo começa aqui.':'Bom ter você de volta.'}</h2><p class="auth-description">${signup?'Uma conta, seus planos e mais clareza para o dia a dia. Comece em poucos segundos.':'Entre no seu espaço e continue de onde parou.'}</p><form id="password-access-form" method="post">${signup?`<label class="field">Como podemos chamar você?<input class="input" type="text" name="name" value="${e(name)}" placeholder="Seu nome" autocomplete="name" maxlength="70" required ${sending?'disabled':''}></label>`:''}<label class="field">Seu e-mail<div class="auth-input-wrap">${icon('mail')}<input class="input" type="email" name="email" value="${e(email)}" placeholder="voce@exemplo.com" autocomplete="username" inputmode="email" autocapitalize="none" spellcheck="false" maxlength="254" required ${sending?'disabled':''}></div></label><label class="field" for="account-password">${signup?'Crie uma senha':'Sua senha'}</label><div class="auth-input-wrap password-wrap">${icon('lock')}<input id="account-password" class="input" type="password" name="password" placeholder="${signup?'Uma senha só sua':'Digite sua senha'}" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="10"':''} maxlength="72" aria-describedby="password-note" required ${sending?'disabled':''}><button class="password-toggle" type="button" data-auth-action="toggle-password" aria-label="Mostrar senha" aria-pressed="false">${icon('eye')}</button></div>${signup?`<div class="password-strength" aria-hidden="true"><i></i><i></i><i></i><i></i></div><p class="password-note" id="password-note">10 ou mais caracteres, com maiúscula, minúscula e número.</p>`:`<p class="password-note" id="password-note">Use a senha que você criou ao se cadastrar.</p>`}<p class="form-error auth-error" role="alert">${e(error)}</p><button class="button auth-primary" type="submit" ${sending||!ready?'disabled':''}><span>${sending?signup?'Criando seu espaço…':'Entrando…':signup?'Criar minha conta':'Entrar na Alva'}</span>${icon(sending?'refresh':'arrow')}</button></form>${!ready?'<div class="auth-availability">O cadastro está sendo preparado. Você já pode conhecer a demonstração.</div>':''}${api.session?'<button type="button" class="button secondary auth-retry" data-auth-action="retry">Tentar abrir minha conta</button>':''}<p class="auth-instant">${icon('check')}Acesso direto, sem código por e-mail.</p></div><div class="auth-trust">${icon('lock')}Seu perfil e seus registros ficam vinculados à sua conta.</div><button class="auth-demo-link" data-auth-action="demo">Explorar a demonstração${icon('chevron')}</button>`}</section></div><footer class="auth-footer"><span>alva · Seu dinheiro, com clareza.</span><span>${icon('leaf')}Um passo de cada vez.</span></footer></main>`;}
 function mounted(){const card=document.querySelector('.auth-card');if(card)card.dataset.transition=lastMode&&lastMode!==mode?'switch':'enter';lastMode=mode;}
 function explain(err){if(err.code==='invalid_credentials'||err.code==='user_not_found')return 'E-mail ou senha incorretos. Confira os dados e tente novamente.';if(err.code==='user_already_exists'||err.code==='email_exists')return 'Não foi possível criar essa conta. Se você já se cadastrou, use Entrar.';if(err.code==='weak_password')return 'Escolha uma senha com pelo menos 10 caracteres, maiúscula, minúscula e número.';if(err.code==='email_not_confirmed')return 'O acesso da sua conta ainda não está liberado. Tente novamente mais tarde.';if(err.status===429)return 'Muitas tentativas em pouco tempo. Aguarde alguns minutos e tente novamente.';if(err.code==='not_configured')return 'O cadastro está sendo preparado. Você já pode explorar a demonstração.';if(err.status===401||err.code==='28000')return 'Sua sessão terminou. Entre novamente para continuar.';if(err.name==='TypeError'||err.name==='TimeoutError')return 'Não foi possível conectar agora. Confira a internet e tente novamente.';if(/schema|function.*not.*found|ensure_alva_account/i.test(err.message))return 'Não foi possível abrir seus dados agora. Tente abrir sua conta novamente.';return err.status?'Não foi possível continuar agora. Confira os dados e tente novamente.':err.message||'Não foi possível continuar. Tente novamente.';}
 async function openAccount(){loading=true;refresh();try{await ctx.onAuthenticated();}catch(err){loading=false;error=explain(err);refresh();}}
 async function click(button){if(button.dataset.authMode){if(sending)return true;mode=button.dataset.authMode;error='';refresh();return true;}const action=button.dataset.authAction;if(!action)return false;if(action==='toggle-password'){const field=document.querySelector('#account-password');if(field){const show=field.type==='password';field.type=show?'text':'password';button.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');button.setAttribute('aria-pressed',String(show));}return true;}if(sending)return true;if(action==='demo')ctx.openDemo();if(action==='retry'){sending=true;try{await openAccount();}finally{sending=false;}}return true;}
 async function submit(form){if(form.getAttribute('id')!=='password-access-form')return false;if(sending)return true;const f=Object.fromEntries(new FormData(form));email=String(f.email||'');name=String(f.name||name);let password=String(f.password||'');sending=true;error='';refresh();try{if(mode==='signup')await api.signUp(email,password,name);else await api.signIn(email,password);password='';delete f.password;await openAccount();}catch(err){loading=false;error=explain(err);}finally{password='';delete f.password;sending=false;if(ctx.isVisible())refresh();}return true;}
 function open(nextMode='signup'){loading=false;mode=nextMode;error='';sending=false;refresh();}
 function input(el){if(el.name==='name')name=el.value;if(el.name==='email')email=el.value;if(el.name==='password'){const checks=[el.value.length>=10,/[a-z]/.test(el.value),/[A-Z]/.test(el.value),/[0-9]/.test(el.value)];const count=el.value?checks.filter(Boolean).length:0;document.querySelectorAll('.password-strength>i').forEach((bar,i)=>bar.classList.toggle('filled',i<count));}}
 return {render,mounted,click,submit,input,open,setLoading:value=>{loading=value;refresh();},fail:err=>{loading=false;error=explain(err);refresh();},stop:()=>{lastMode='';}};
}
